class UserMapper {
public:
    static UserResponseDTO toResponse(const User& user) {
        return UserResponseDTO(
            std::to_string(user.id()),
            user.name(),
            user.email(),
            formatTimestamp(user.createdAt())
        );
    }

    static std::vector<UserResponseDTO> toResponseList(const std::vector<User>& users) {
        std::vector<UserResponseDTO> out;
        out.reserve(users.size());
        for (const auto& user : users) out.push_back(toResponse(user));
        return out;
    }

    static User toDomain(const CreateUserRequestDTO& dto) {
        return User(Uuid::random(), dto.name, dto.email,
                    hashPassword(dto.password), Role::USER);
    }
};

