struct CreateUserRequestDTO {
    std::string name;      // required, must not be blank
    std::string email;     // required, must look like an email
    std::string password;  // required, at least 8 characters

    // C++ has no validation annotations, so the same contract is
    // enforced in one place, at the edge, before the DTO is used
    std::vector<std::string> validate() const {
        std::vector<std::string> errors;
        if (name.empty())                errors.push_back("name must not be blank");
        if (!looksLikeEmail(email))      errors.push_back("email is not valid");
        if (password.size() < 8)         errors.push_back("password must be at least 8 characters");
        return errors;
    }
};

